import{C as a,o as s,c as o,a5 as e,E as n}from"./chunks/framework.URF5zJ_R.js";const y=JSON.parse('{"title":"42 个高可用系统设计核心基石 (Building Blocks)","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"05_Building_Blocks.md","filePath":"05_Building_Blocks.md","lastUpdated":1789004603000}'),c={name:"05_Building_Blocks.md"},f=Object.assign(c,{setup(i){const d=[{index:"01",title:"API Gateway vs 负载均衡 (Load Balancer)",category:"流量接入层",desc:"L4/L7 纯流量均衡解决单点分流；API Gateway 则承载路由、统一鉴权、速率限制、SSL 卸载与协议转换。",meta:{核心选型:"Kong · Envoy · AWS ALB · Nginx","⚠️ 切忌反模式":"单一内部服务增加不必要网络跳数"}},{index:"02",title:"分布式缓存 (Redis) vs 进程内缓存 (In-Process)",category:"性能加速层",desc:"Redis 解决多实例共享与大容量缓存；Caffeine/Guava 提供纳秒级极致速度但存在多节点数据不一致。",meta:{核心选型:"Redis · Memcached · Caffeine","⚠️ 切忌反模式":"对绝对强一致性数据切忌无条件缓存"}},{index:"03",title:"关系型数据库 vs 宽表存储 (Cassandra/ScyllaDB)",category:"数据存储层",desc:"PostgreSQL/MySQL 保证强 ACID 与多表关联；ScyllaDB/Cassandra 针对海量高频写与万亿级单表极度优化。",meta:{核心选型:"PostgreSQL · ScyllaDB · MongoDB","⚠️ 切忌反模式":"宽表切忌用于多表 Join 与复杂事务查询"}},{index:"04",title:"消息队列 (RabbitMQ) vs 事件流 (Kafka)",category:"异步解耦层",desc:"RabbitMQ 适合点对点任务队列且消费即销毁；Kafka 作为持久化追加日志，支持严格顺序、多消费者与历史回溯。",meta:{核心选型:"Apache Kafka · RabbitMQ · Pulsar","⚠️ 切忌反模式":"简单短平快任务切忌滥用 Kafka"}},{index:"05",title:"限流器 (Rate Limiter) & 熔断器 (Circuit Breaker)",category:"高可用容灾",desc:"限流器保护本系统不被流量洪峰打垮；熔断器在下游不可用时主动快速截断，防止级联雪崩与线程池耗尽。",meta:{核心选型:"Envoy · Redis Token Bucket · Resilience4j","⚠️ 切忌反模式":"高度信任的低延时内部调用切忌盲目限流"}},{index:"06",title:"对象存储 (S3) vs 块存储 (EBS)",category:"海量存储层",desc:"S3/MinIO 提供海量非结构化不可变文件存储（图片、视频、备份），通过预签名直传解耦应用服务器带宽。",meta:{核心选型:"Amazon S3 · MinIO · Cloudflare R2","⚠️ 切忌反模式":"低延迟高频随机点查切忌依赖对象存储"}}];return(g,t)=>{const l=a("CardGrid");return s(),o("div",null,[t[0]||(t[0]=e('<h1 id="_42-个高可用系统设计核心基石-building-blocks" tabindex="-1">42 个高可用系统设计核心基石 (Building Blocks) <a class="header-anchor" href="#_42-个高可用系统设计核心基石-building-blocks" aria-label="Permalink to &quot;42 个高可用系统设计核心基石 (Building Blocks)&quot;">​</a></h1><blockquote><p><em>现代分布式架构的 42 块基石组件：功能定位、适用场景、反模式（何时切忌使用）以及工业界主流开源与云端选型。</em></p></blockquote><hr><div class="tip custom-block"><p class="custom-block-title">💡 架构师避坑心法：反模式（Anti-Patterns）才是面试高分分水岭</p><p>很多初中级候选人在系统设计面试中容易陷入“工具堆砌”的误区，无论题目规模大小直接抛出 Kafka、K8s、Redis 和微服务。</p><p><strong>资深考官考察的核心是“权衡与取舍”</strong>：</p><ul><li>每一个引入的组件都带来了分布式复杂性（网络往返延迟、数据最终一致性难题、运维与故障面扩大）。</li><li>清楚阐明**“何时切忌使用某组件（反模式）”**（如“在要求严格实时事务的账户扣款场景下切忌无脑引入只支持最终一致性的 NoSQL”），往往比单纯背诵组件功能更能证明你的架构深度。</li></ul></div><hr><h2 id="🏛️-现代分布式系统-8-大基础设施层" tabindex="-1">🏛️ 现代分布式系统 8 大基础设施层 <a class="header-anchor" href="#🏛️-现代分布式系统-8-大基础设施层" aria-label="Permalink to &quot;🏛️ 现代分布式系统 8 大基础设施层&quot;">​</a></h2><p>分布式系统的 42 个基石组件在工业级落地中形成了清晰的层级协作网络：</p><div class="stats-grid" style="margin-bottom:2rem;"><div class="stat-card"><div class="stat-icon">🚦</div><div class="stat-info"><span class="stat-number">5 组件</span><span class="stat-label">流量网关与分发</span></div></div><div class="stat-card"><div class="stat-icon">⚡</div><div class="stat-info"><span class="stat-number">2 组件</span><span class="stat-label">多级缓存体系</span></div></div><div class="stat-card"><div class="stat-icon">🗄️</div><div class="stat-info"><span class="stat-number">11 组件</span><span class="stat-label">存储与数据库</span></div></div><div class="stat-card"><div class="stat-icon">📨</div><div class="stat-info"><span class="stat-number">3 组件</span><span class="stat-label">消息与事件流</span></div></div><div class="stat-card"><div class="stat-icon">⚙️</div><div class="stat-info"><span class="stat-number">6 组件</span><span class="stat-label">异步与批流计算</span></div></div><div class="stat-card"><div class="stat-icon">🛡️</div><div class="stat-info"><span class="stat-number">4 组件</span><span class="stat-label">高可用与容灾</span></div></div><div class="stat-card"><div class="stat-icon">🤝</div><div class="stat-info"><span class="stat-number">4 组件</span><span class="stat-label">分布式协调管理</span></div></div><div class="stat-card"><div class="stat-icon">🔭</div><div class="stat-info"><span class="stat-number">7 组件</span><span class="stat-label">可观测与安全</span></div></div></div><hr><h2 id="🏆-6-大高频基石组件深度选型对比-core-architectural-highlights" tabindex="-1">🏆 6 大高频基石组件深度选型对比 (Core Architectural Highlights) <a class="header-anchor" href="#🏆-6-大高频基石组件深度选型对比-core-architectural-highlights" aria-label="Permalink to &quot;🏆 6 大高频基石组件深度选型对比 (Core Architectural Highlights)&quot;">​</a></h2><p>以下是系统设计面试中出现频次最高、最容易被考官追问“为什么选它而不是另一个”的 6 组核心组件对比：</p>',11)),n(l,{items:d,columns:3}),t[1]||(t[1]=e('<hr><h2 id="📚-42-个架构基石组件全景清单-complete-42-building-blocks" tabindex="-1">📚 42 个架构基石组件全景清单 (Complete 42 Building Blocks) <a class="header-anchor" href="#📚-42-个架构基石组件全景清单-complete-42-building-blocks" aria-label="Permalink to &quot;📚 42 个架构基石组件全景清单 (Complete 42 Building Blocks)&quot;">​</a></h2><blockquote><p><em>支持在下方表格工具栏输入技术关键词（如 <code>Redis</code>、<code>Kafka</code>、<code>Database</code>、<code>Lock</code>、<code>Security</code>）快速筛选。移动端自动折叠为卡片流。</em></p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th style="text-align:left;">组件名称</th><th style="text-align:left;">分类</th><th style="text-align:left;">核心功能定位</th><th style="text-align:left;">何时应当使用 (适用场景)</th><th style="text-align:left;">⚠️ 何时切忌使用 (反模式)</th><th style="text-align:left;">工业界常用工具选型</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:left;"><strong>Load balancer</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">将网络请求分发到多台健康的后端服务器</td><td style="text-align:left;">拥有多台服务实例的任何分布式生产系统</td><td style="text-align:left;">单机内部工具，引入只会增加无谓网络延迟与运维复杂度</td><td style="text-align:left;"><code>Nginx</code> <code>HAProxy</code> <code>AWS ALB</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">2</td><td style="text-align:left;"><strong>Reverse proxy</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">处于服务前端处理 TLS 加密、反向路由与流量缓冲</td><td style="text-align:left;">卸载 TLS、托管静态物料、隐藏内部微服务网络拓扑</td><td style="text-align:left;">极小型应用且现有后端框架内置轻量处理已完全够用时</td><td style="text-align:left;"><code>Nginx</code> <code>Caddy</code> <code>Envoy</code> <code>Traefik</code></td></tr><tr><td style="text-align:center;">3</td><td style="text-align:left;"><strong>API gateway</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">外部流量统一入口，集中处理认证鉴权、路由限流</td><td style="text-align:left;">面向多端客户端的大型微服务集群</td><td style="text-align:left;">简单单体服务，API 网关会成为完全多余的额外网络跳转</td><td style="text-align:left;"><code>Kong</code> <code>AWS API Gateway</code> <code>Apigee</code> <code>Envoy</code></td></tr><tr><td style="text-align:center;">4</td><td style="text-align:left;"><strong>CDN</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">边缘节点就近缓存与加速内容分发</td><td style="text-align:left;">静态资源、图片、音视频分发及全球化受众站点</td><td style="text-align:left;">高度定制化、每次请求均不同的私有动态未缓存内容</td><td style="text-align:left;"><code>Cloudflare</code> <code>Akamai</code> <code>CloudFront</code> <code>Fastly</code></td></tr><tr><td style="text-align:center;">5</td><td style="text-align:left;"><strong>DNS load balancing</strong></td><td style="text-align:left;"><code>Traffic</code></td><td style="text-align:left;">将用户智能解析路由至物理最近或最健康的机房</td><td style="text-align:left;">跨地域（Multi-Region）多活或多中心部署</td><td style="text-align:left;">精细化流量路由控制；DNS 递归缓存会导致容灾切换滞后</td><td style="text-align:left;"><code>AWS Route 53</code> <code>Cloudflare DNS</code></td></tr><tr><td style="text-align:center;">6</td><td style="text-align:left;"><strong>Application cache</strong></td><td style="text-align:left;"><code>Caching</code></td><td style="text-align:left;">内存中暂存高频读取数据，大幅削减数据库压力</td><td style="text-align:left;">读多写少、且业务能容忍适度毫秒级数据延迟的场景</td><td style="text-align:left;">数据必须保证强一致性与绝对实时性的核心交易链路</td><td style="text-align:left;"><code>Redis</code> <code>Memcached</code> <code>Valkey</code></td></tr><tr><td style="text-align:center;">7</td><td style="text-align:left;"><strong>Local/in-process cache</strong></td><td style="text-align:left;"><code>Caching</code></td><td style="text-align:left;">应用进程内存直接缓存（如 JVM 堆内缓存）</td><td style="text-align:left;">超高频访问、体积小巧且几乎不发生变化的静态字典</td><td style="text-align:left;">多实例部署且要求跨节点严格状态一致的业务场景</td><td style="text-align:left;"><code>Caffeine</code> <code>Guava</code> <code>In-memory Maps</code></td></tr><tr><td style="text-align:center;">8</td><td style="text-align:left;"><strong>Database read replica</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">主数据库的只读副本，物理分流读取请求</td><td style="text-align:left;">能够容忍主从复制延迟（Replication Lag）的读多写少系统</td><td style="text-align:left;">要求“写后立即读”（Read-your-writes）且未做路由处理的链路</td><td style="text-align:left;"><code>PostgreSQL Streaming</code> <code>MySQL Replicas</code></td></tr><tr><td style="text-align:center;">9</td><td style="text-align:left;"><strong>Relational database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">严格支持 ACID 事务、固定 Schema 与复杂关系表 Join</td><td style="text-align:left;">涉及资金财务、实体强关联与数据完整性要求严苛的场景</td><td style="text-align:left;">极端高并发写入、海量无规律动态字段或纯键值存取</td><td style="text-align:left;"><code>PostgreSQL</code> <code>MySQL</code> <code>AWS Aurora</code></td></tr><tr><td style="text-align:center;">10</td><td style="text-align:left;"><strong>Wide-column store</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">列族分布式存储，针对海量极高并发写入极致优化</td><td style="text-align:left;">时间序列、日志事件、万亿级消息与社交活动数据流</td><td style="text-align:left;">含有多表关联 Join 查询或复杂多条件过滤的业务场景</td><td style="text-align:left;"><code>Cassandra</code> <code>ScyllaDB</code> <code>HBase</code> <code>Bigtable</code></td></tr><tr><td style="text-align:center;">11</td><td style="text-align:left;"><strong>Document database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">灵活半结构化文档（JSON/BSON）存储</td><td style="text-align:left;">数据模型频繁快速演进、实体高度聚合且结构多变</td><td style="text-align:left;">含有密集跨文档关系 Join 以及严苛多文档分布式事务场景</td><td style="text-align:left;"><code>MongoDB</code> <code>DynamoDB</code> <code>Firestore</code></td></tr><tr><td style="text-align:center;">12</td><td style="text-align:left;"><strong>Key-value store</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">极简、纳秒/微秒级主键直接点查存取</td><td style="text-align:left;">用户会话（Session）、缓存、分布式特性开关与字典查找</td><td style="text-align:left;">需要按非主键（Non-Key）字段进行复杂范围或模糊检索</td><td style="text-align:left;"><code>Redis</code> <code>DynamoDB</code> <code>etcd</code></td></tr><tr><td style="text-align:center;">13</td><td style="text-align:left;"><strong>Graph database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">将实体间关系作为一等公民存储并支持极速图遍历</td><td style="text-align:left;">社交好友网络、金融反欺诈黑产图谱、知识图谱与推荐引擎</td><td style="text-align:left;">仅包含扁平二维行列表格且无需进行关系多跳遍历的场景</td><td style="text-align:left;"><code>Neo4j</code> <code>AWS Neptune</code> <code>JanusGraph</code></td></tr><tr><td style="text-align:center;">14</td><td style="text-align:left;"><strong>Time-series database</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">针对带有时间戳的度量指标做写入与降采样压缩优化</td><td style="text-align:left;">基础设施监控指标采集、物联网传感器时序数据、金融逐笔报价</td><td style="text-align:left;">通用业务事务处理，频繁更新历史旧记录的业务场景</td><td style="text-align:left;"><code>InfluxDB</code> <code>TimescaleDB</code> <code>Prometheus</code></td></tr><tr><td style="text-align:center;">15</td><td style="text-align:left;"><strong>Search index</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">倒排索引支持全文检索、动态分面筛选与相关度打分</td><td style="text-align:left;">包含搜索框、长文本模糊检索与高维度筛选的任何产品</td><td style="text-align:left;">纯基于主键的精确查找（主数据库即可毫秒完成）</td><td style="text-align:left;"><code>Elasticsearch</code> <code>OpenSearch</code> <code>Typesense</code> <code>Solr</code></td></tr><tr><td style="text-align:center;">16</td><td style="text-align:left;"><strong>OLAP / data warehouse</strong></td><td style="text-align:left;"><code>Database</code></td><td style="text-align:left;">列式存储支撑海量数据的分析聚合与多维统计</td><td style="text-align:left;">实时经营大盘、报表统计、BI 商业智能与数仓建模</td><td style="text-align:left;">低延迟的点查修改或高频单行级 OLTP 事务操作</td><td style="text-align:left;"><code>Snowflake</code> <code>BigQuery</code> <code>ClickHouse</code> <code>Redshift</code></td></tr><tr><td style="text-align:center;">17</td><td style="text-align:left;"><strong>Object storage</strong></td><td style="text-align:left;"><code>Storage</code></td><td style="text-align:left;">极高持久性、廉价的大规模非结构化文件二进制存储</td><td style="text-align:left;">图片、视频流媒体、数据备份归档与数据湖物料存储</td><td style="text-align:left;">毫秒级低延迟随机读写或含有行级事务修改的数据</td><td style="text-align:left;"><code>Amazon S3</code> <code>Google Cloud Storage</code> <code>MinIO</code></td></tr><tr><td style="text-align:center;">18</td><td style="text-align:left;"><strong>Block storage</strong></td><td style="text-align:left;"><code>Storage</code></td><td style="text-align:left;">直接挂载到计算实例上的持久化高性能虚拟硬盘</td><td style="text-align:left;">数据库底层数据文件存放、需要标准本地文件系统的应用</td><td style="text-align:left;">需要跨多个异地计算节点同时并发进行网络共享读写</td><td style="text-align:left;"><code>AWS EBS</code> <code>GCP Persistent Disk</code></td></tr><tr><td style="text-align:center;">19</td><td style="text-align:left;"><strong>Message queue</strong></td><td style="text-align:left;"><code>Messaging</code></td><td style="text-align:left;">生产端与消费端之间的异步解耦与工作缓冲</td><td style="text-align:left;">削峰填谷、解耦依赖服务、长耗时后台任务异步化</td><td style="text-align:left;">真正要求强同步（Request-Response）等待返回结果的链路</td><td style="text-align:left;"><code>RabbitMQ</code> <code>AWS SQS</code> <code>Redis Streams</code></td></tr><tr><td style="text-align:center;">20</td><td style="text-align:left;"><strong>Event log / stream</strong></td><td style="text-align:left;"><code>Messaging</code></td><td style="text-align:left;">持久化、严格有序且支持历史回放的追加式日志</td><td style="text-align:left;">事件驱动架构（Event Sourcing）、多订阅者与数据回放</td><td style="text-align:left;">简单的临时点对点任务分发（此时 Kafka 显得过于庞大复杂）</td><td style="text-align:left;"><code>Apache Kafka</code> <code>Pulsar</code> <code>AWS Kinesis</code> <code>Redpanda</code></td></tr><tr><td style="text-align:center;">21</td><td style="text-align:left;"><strong>Pub/sub</strong></td><td style="text-align:left;"><code>Messaging</code></td><td style="text-align:left;">一处发布、多个独立消费者并行订阅与广播处理</td><td style="text-align:left;">事件广播通知、多系统数据同步与事件驱动扇出</td><td style="text-align:left;">保证单一消费者独占消费、按需精细化任务竞争处理的场景</td><td style="text-align:left;"><code>Kafka</code> <code>Google Cloud Pub/Sub</code> <code>AWS SNS</code> <code>NATS</code></td></tr><tr><td style="text-align:center;">22</td><td style="text-align:left;"><strong>Task scheduler</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">按照固定定时周期或特定延迟调度执行后台作业</td><td style="text-align:left;">周期性生成分析报表、定时数据清理、消息提醒与重试调度</td><td style="text-align:left;">立即要求毫秒级返回的同步请求链路</td><td style="text-align:left;"><code>Apache Airflow</code> <code>Temporal</code> <code>Quartz</code> <code>cron</code></td></tr><tr><td style="text-align:center;">23</td><td style="text-align:left;"><strong>Worker pool</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">异步消费并并行处理任务队列中的工作负载</td><td style="text-align:left;">耗时超过常规 HTTP 响应生命周期（如 &gt;500ms）的一切后台计算</td><td style="text-align:left;">亚毫秒级（Sub-millisecond）极速内联计算操作</td><td style="text-align:left;"><code>Celery</code> <code>Sidekiq</code> <code>BullMQ</code> <code>Hangfire</code></td></tr><tr><td style="text-align:center;">24</td><td style="text-align:left;"><strong>Serverless functions</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">事件触发式无服务器运行时，无需自行管理主机</td><td style="text-align:left;">流量高度突发、低频触发或纯事件驱动的小型轻量任务</td><td style="text-align:left;">长时间运行的大型计算或对冷启动延迟（Cold Start）极度敏感的任务</td><td style="text-align:left;"><code>AWS Lambda</code> <code>Cloud Functions</code> <code>Azure Functions</code></td></tr><tr><td style="text-align:center;">25</td><td style="text-align:left;"><strong>Container orchestrator</strong></td><td style="text-align:left;"><code>Compute</code></td><td style="text-align:left;">自动化调度、水平扩缩容与自愈容器化微服务集群</td><td style="text-align:left;">具有一定规模、包含多服务协作的中大型系统</td><td style="text-align:left;">单一极简小型服务；Kubernetes 本身的心智与运维开销极大</td><td style="text-align:left;"><code>Kubernetes</code> <code>AWS ECS</code> <code>Nomad</code></td></tr><tr><td style="text-align:center;">26</td><td style="text-align:left;"><strong>Stream processor</strong></td><td style="text-align:left;"><code>Processing</code></td><td style="text-align:left;">对无限事件流执行毫秒级连续计算与滑动窗口聚合</td><td style="text-align:left;">实时风控反欺诈、滑动窗口指标统计、实时数据补全丰富</td><td style="text-align:left;">对延迟毫无要求的离线隔天批量全量统计</td><td style="text-align:left;"><code>Apache Flink</code> <code>Kafka Streams</code> <code>Spark Streaming</code></td></tr><tr><td style="text-align:center;">27</td><td style="text-align:left;"><strong>Batch processor</strong></td><td style="text-align:left;"><code>Processing</code></td><td style="text-align:left;">大规模数据集的大吞吐周期性离线分布式计算</td><td style="text-align:left;">隔夜财务对账、离线 ETL 数据清洗、机器学习模型特征生成</td><td style="text-align:left;">要求秒级或分钟级新鲜度的即时在线查询系统</td><td style="text-align:left;"><code>Apache Spark</code> <code>Hadoop</code> <code>dbt</code> <code>Airflow</code></td></tr><tr><td style="text-align:center;">28</td><td style="text-align:left;"><strong>Rate limiter</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">针对用户、IP 或租户限制单位时间内的请求速率</td><td style="text-align:left;">任何面向公网的开放 API、高防撞库与抗恶意爬虫入口</td><td style="text-align:left;">内部高度信任、流量受控且调用极为频繁的内部服务间调用</td><td style="text-align:left;"><code>Redis Token Bucket</code> <code>Envoy</code> <code>API Gateway</code></td></tr><tr><td style="text-align:center;">29</td><td style="text-align:left;"><strong>Circuit breaker</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">下游故障时自动断开调用并快速失败，防止级联雪崩</td><td style="text-align:left;">对外部依赖服务、跨网络第三方的任何强同步 RPC 调用</td><td style="text-align:left;">进程内部的方法直接调用</td><td style="text-align:left;"><code>Resilience4j</code> <code>Polly</code> <code>Envoy</code> <code>Hystrix</code></td></tr><tr><td style="text-align:center;">30</td><td style="text-align:left;"><strong>Service discovery</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">允许动态扩缩容的微服务实例自动注册与相互寻址</td><td style="text-align:left;">容器频繁启停、IP 地址动态变化的云原生微服务网络</td><td style="text-align:left;">节点数量固定、长期运行在静态单一环境的极简部署</td><td style="text-align:left;"><code>HashiCorp Consul</code> <code>Eureka</code> <code>K8s CoreDNS</code></td></tr><tr><td style="text-align:center;">31</td><td style="text-align:left;"><strong>Service mesh</strong></td><td style="text-align:left;"><code>Reliability</code></td><td style="text-align:left;">透明接管服务间通信，提供 mTLS 加密、链路追踪与流控</td><td style="text-align:left;">拥有数十乃至上百个异构服务的大型微服务资产群</td><td style="text-align:left;">服务数量少于 10 个的小型项目；网络拦截开销远大于收益</td><td style="text-align:left;"><code>Istio</code> <code>Linkerd</code> <code>Consul Connect</code></td></tr><tr><td style="text-align:center;">32</td><td style="text-align:left;"><strong>Distributed lock</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">保证跨多个物理进程/节点同一时刻仅有一个在执行</td><td style="text-align:left;">分布式主节点选举、防止重复消费、库存扣减防超卖</td><td style="text-align:left;">能通过天然数据库原子操作（如 CAS、幂等键）优雅解决的场景</td><td style="text-align:left;"><code>Redis Redlock</code> <code>Apache ZooKeeper</code> <code>etcd</code></td></tr><tr><td style="text-align:center;">33</td><td style="text-align:left;"><strong>Consensus / coordination service</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">在不可靠分布式网络节点间达成共享强一致状态共识</td><td style="text-align:left;">分布式 Leader 选举、分布式配置注册中心、集群元数据管理</td><td style="text-align:left;">单一数据库事务即可搞定的简单单体系统</td><td style="text-align:left;"><code>Apache ZooKeeper</code> <code>etcd</code> <code>Consul</code></td></tr><tr><td style="text-align:center;">34</td><td style="text-align:left;"><strong>Configuration service</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">集中化、热更新式管理全集群多服务配置</td><td style="text-align:left;">包含数十个微服务且需要在不停机前提下动态调整参数的系统</td><td style="text-align:left;">单一独立服务且使用环境变量与本地文件即可简单解决的情况</td><td style="text-align:left;"><code>Spring Cloud Config</code> <code>Consul</code> <code>AWS AppConfig</code></td></tr><tr><td style="text-align:center;">35</td><td style="text-align:left;"><strong>Feature flag service</strong></td><td style="text-align:left;"><code>Coordination</code></td><td style="text-align:left;">无需重新部署即可在毫秒级动态开关或灰度特定功能</td><td style="text-align:left;">渐进式金丝雀发布、生产环境安全应急降级开关（Kill Switch）</td><td style="text-align:left;">极少数人维护且极低频发布变更的简易业余项目</td><td style="text-align:left;"><code>LaunchDarkly</code> <code>Unleash</code> <code>Flagsmith</code></td></tr><tr><td style="text-align:center;">36</td><td style="text-align:left;"><strong>Metrics and monitoring</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">采集并存储数值型时序性能指标，提供实时报警大盘</td><td style="text-align:left;">任何严肃的生产级系统，绝无例外</td><td style="text-align:left;">永远切忌不使用；监控是生产系统的生命线，绝不可省</td><td style="text-align:left;"><code>Prometheus</code> <code>Grafana</code> <code>Datadog</code> <code>CloudWatch</code></td></tr><tr><td style="text-align:center;">37</td><td style="text-align:left;"><strong>Distributed tracing</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">为每个请求生成全局唯一的 Trace ID 跟踪跨微服务全调用链</td><td style="text-align:left;">含有 3 个以上微服务的任何分布式异步系统</td><td style="text-align:left;">单体单机系统，仅查看本地单机请求日志即可排查问题</td><td style="text-align:left;"><code>OpenTelemetry</code> <code>Jaeger</code> <code>Tempo</code> <code>Zipkin</code></td></tr><tr><td style="text-align:center;">38</td><td style="text-align:left;"><strong>Centralised logging</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">集中收集、格式化、索引并检索全部服务节点的运行日志</td><td style="text-align:left;">任何多实例多主机的现代化生产部署环境</td><td style="text-align:left;">仅有一台云服务器且你可以随时 SSH 登录查看 log 文件的场景</td><td style="text-align:left;"><code>Elasticsearch (ELK)</code> <code>Grafana Loki</code> <code>Splunk</code></td></tr><tr><td style="text-align:center;">39</td><td style="text-align:left;"><strong>Error tracking</strong></td><td style="text-align:left;"><code>Observability</code></td><td style="text-align:left;">自动捕获运行时未捕获异常、堆栈信息并聚合报警</td><td style="text-align:left;">面向真实用户的一切前端网页、移动端 App 与后端核心服务</td><td style="text-align:left;">永远切忌不使用；各类工具均有免费额度，部署接入成本极低</td><td style="text-align:left;"><code>Sentry</code> <code>Rollbar</code> <code>Bugsnag</code></td></tr><tr><td style="text-align:center;">40</td><td style="text-align:left;"><strong>Identity provider</strong></td><td style="text-align:left;"><code>Security</code></td><td style="text-align:left;">集中化管理用户身份认证、单点登录（SSO）与 Token 签发</td><td style="text-align:left;">包含终端用户登录、特别是由多个子服务构成的复杂系统</td><td style="text-align:left;">仅有单一极简页面且使用经典 Session 即可胜任的应用</td><td style="text-align:left;"><code>Auth0</code> <code>Keycloak</code> <code>Microsoft Entra ID</code> <code>Cognito</code></td></tr><tr><td style="text-align:center;">41</td><td style="text-align:left;"><strong>Secrets manager</strong></td><td style="text-align:left;"><code>Security</code></td><td style="text-align:left;">安全加密存储数据库密码、API Key 等敏感凭据并支持轮换</td><td style="text-align:left;">生产系统的所有凭据管理，杜绝将密码硬编码提交至 Git</td><td style="text-align:left;">永远切忌不使用；将密码明文硬编码于仓库是最高频安全灾难</td><td style="text-align:left;"><code>HashiCorp Vault</code> <code>AWS Secrets Manager</code> <code>Doppler</code></td></tr><tr><td style="text-align:center;">42</td><td style="text-align:left;"><strong>WAF / DDoS protection</strong></td><td style="text-align:left;"><code>Security</code></td><td style="text-align:left;">在互联网边缘网络过滤 SQL 注入、XSS 攻击与洪峰流量清洗</td><td style="text-align:left;">任何面向公网开放的生产服务与门户入口</td><td style="text-align:left;">完全隐藏在内网 VPN 之后、绝不对外开放的纯内部管理工具</td><td style="text-align:left;"><code>Cloudflare WAF</code> <code>AWS WAF</code> <code>Akamai</code></td></tr></tbody></table><hr>',5))])}}});export{y as __pageData,f as default};
